mapper.select:



        and name like concat('%', #{name}, '%')


        and type_id = #{typeId}


        and platform_id = #{platformId}


        and kind_id = #{kindId}


        and maintain = #{maintain}


        and recommend = #{recommend}


        and large_icon = #{largeIcon}


        and effect = #{effect}


order by sort asc

select p.game_category, p.maintain platform_maintain, a.* from (select i.id, i.name, i.icon, i.maintain, i.recommend, i.large_icon, i.kind_id, i.platform_id, i.sort from game_info i where i.effect = 1
and i.type_id = #{typeId}
and i.recommend = 1) a left join game_platform p on p.id = a.platform_id where p.effect = 1 order by a.sort asc
